-- Japan deep-dive ES/DE/FR translations (completing 366).
-- INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Facturación electrónica voluntaria (JP PINT / Peppol) superpuesta a un Sistema de Facturas Cualificadas obligatorio en papel o electrónico desde 2023 -- sin mandato de emisión de facturación electrónica', 'Esta página de análisis refleja la orientación pública de la Agencia Digital y la Agencia Nacional Tributaria, así como información del sector, disponible a principios de agosto de 2026, y se ofrece a título informativo general, no como asesoramiento legal o fiscal. Confirme el estado actual directamente con la NTA, la Agencia Digital o un asesor fiscal japonés antes de basar en esta página sus decisiones de cumplimiento.', 'La Agencia Digital de Japón se creó en septiembre de 2021 y se convirtió en la Autoridad Peppol del país; un mes después, se abrió el registro para el Sistema de Facturas Cualificadas, que entró en vigor el 1 de octubre de 2023. JP PINT, un estándar Peppol voluntario de facturación electrónica, se ha desarrollado en paralelo, mientras que el alivio transitorio del crédito fiscal para proveedores no registrados se reduce gradualmente hasta 2031.', 'No existe un formato de archivo de factura obligatorio en Japón -- las facturas cualificadas pueden ser en papel, PDF o cualquier otro formato, siempre que contengan el contenido exigido. Las empresas que opten por facturar electrónicamente pueden usar JP PINT, la especificación voluntaria de Japón conforme con Peppol PINT BIS Billing, mantenida por la Agencia Digital.', 'En Japón no se aplica ningún mandato de emisión de facturación electrónica B2B ni B2G -- toda empresa sigue siendo libre de enviar facturas en papel, PDF o electrónicas. El Sistema de Facturas Cualificadas regula en cambio el CONTENIDO de la factura y el registro del proveedor a efectos del crédito fiscal del impuesto al consumo, y se aplica siempre que un cliente empresarial quiera reclamar ese crédito, independientemente del formato o de cómo se transmita la factura.', 'Dado que Japón no tiene ningún mandato de emisión para el que prepararse, la mayor parte del trabajo práctico aquí consiste en el registro y los requisitos de contenido del Sistema de Facturas Cualificadas -- además de decidir, de forma totalmente opcional, si la adopción de JP PINT/Peppol vale la pena para sus relaciones comerciales.', 'El Sistema de Facturas Cualificadas de Japón no impone ninguna sanción financiera directa a una empresa que no se registra -- el mecanismo de aplicación es económico, no punitivo: las facturas de un proveedor no registrado no permiten a sus clientes empresariales deducir el crédito fiscal soportado en su totalidad, una desventaja de mercado en lugar de una multa.', 'Japón no tiene ningún mandato de emisión de facturación electrónica -- las facturas en papel y PDF siguen siendo plenamente válidas. Lo que sí es obligatorio, desde el 1 de octubre de 2023, es el Sistema de Facturas Cualificadas: para reclamar el crédito fiscal soportado, un cliente empresarial generalmente necesita una factura de un proveedor registrado ante la NTA que contenga un contenido específico, incluido un número T de 14 dígitos -- un régimen de registro y documentación, no una norma de formato de transmisión. Por separado, la Agencia Digital ha promovido JP PINT, un estándar voluntario de facturación electrónica basado en Peppol, desde 2021. El alivio transitorio del crédito por compras a proveedores no registrados ya se está reduciendo gradualmente hasta 2031.', '🇯🇵' FROM countries WHERE name_en = 'Japan';

