INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Contenido obligatorio de la factura cualificada', '[["Datos del emisor", "Nombre del emisor y número T de 14 dígitos (número de registro)"], ["Fecha de emisión", "Fecha en que se emitió la factura"], ["Descripción detallada", "Descripción de los bienes o servicios suministrados"], ["Importes diferenciados por tipo impositivo", "Importes desglosados según el tipo de impuesto al consumo aplicable (estándar/reducido)"], ["Total del impuesto al consumo", "Importe total del impuesto al consumo de la factura"]]', 'Nada de esto exige que la factura se emita electrónicamente -- una factura en papel o PDF que contenga este contenido es una factura cualificada plenamente válida.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Especificación JP PINT / Peppol (voluntaria)', '[["Estándar", "JP PINT -- la especificación de facturación electrónica de Japón conforme con Peppol PINT BIS Billing"], ["Gobernanza", "Desarrollada por la Agencia Digital junto con EIPA, un organismo sectorial japonés"], ["Versión actual", "v1.1.3 (a 8 de junio de 2026), que cubre la Standard Invoice JP PINT, la JP BIS Self-Billing Invoice y la JP BIS Invoice for Non-tax-Registered Businesses"], ["Estatus legal", "Totalmente voluntario -- ninguna ley exige su adopción"]]', 'JP PINT es una especificación real y activamente mantenida -- simplemente no es obligatoria para ninguna empresa.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Registro y conservación', '[["Autoridad de registro", "Agencia Nacional Tributaria (NTA)"], ["Ventana de registro", "Abierta desde el 1 de octubre de 2021, antes de la entrada en vigor el 1 de octubre de 2023"], ["Formato del número T", "Un número de registro de 14 dígitos asignado a cada emisor de facturas cualificadas registrado"], ["Plazo de conservación", "Mínimo 7 años para las facturas cualificadas y los registros relacionados"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo voluntario de JP PINT/Peppol', 'Para la minoría de empresas que optan por facturar electrónicamente mediante JP PINT, una factura recorre esta secuencia -- totalmente opcional en cada paso:', 'Nada de este flujo es obligatorio. La mayoría de las empresas japonesas siguen intercambiando facturas en papel o PDF y siguen cumpliendo plenamente con el Sistema de Facturas Cualificadas siempre que el contenido de la factura sea correcto.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El sistema del proveedor genera una factura electrónica con formato JP PINT' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Se envía a través del Punto de Acceso Peppol del proveedor' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Se transmite a través de la red Peppol de cuatro esquinas' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Se entrega al Punto de Acceso del comprador' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Se recibe directamente en el sistema del comprador como datos estructurados' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Qué es realmente obligatorio frente a voluntario, por capas', '[["Formato/emisión de la factura", "No obligatorio -- papel, PDF o electrónico, todos válidos"], ["Contenido y registro de la factura cualificada", "Obligatorio desde el 1 oct. 2023, a efectos del crédito fiscal soportado"], ["Adopción de JP PINT / Peppol", "Totalmente voluntaria, estándar respaldado por el gobierno"], ["Mandato general de facturación electrónica B2B", "No existe -- no se encontró ninguna propuesta con calendario fijado"]]', 'Es fácil confundir el verdadero mandato fiscal de 2023 de Japón con un mandato de facturación electrónica -- no son lo mismo. Solo el primero es legalmente obligatorio.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'La reducción escalonada del alivio transitorio', '[["1 oct. 2023 - 30 sep. 2026", "80% del impuesto en compras a proveedores no registrados es deducible"], ["1 oct. 2026 - 30 sep. 2028", "70% deducible"], ["1 oct. 2028 - 30 sep. 2030", "50% deducible"], ["1 oct. 2030 - 30 sep. 2031", "30% deducible"]]', 'La fuente de la NTA consultada no confirmó explícitamente el desenlace tras septiembre de 2031 -- considere la eliminación total después de esa fecha como esperada, no oficialmente confirmada aquí.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💰 Sin multa directa por no registrarse', NULL, NULL, 'A diferencia de muchas jurisdicciones de este seguimiento, el Sistema de Facturas Cualificadas de Japón no impone ninguna sanción financiera directa a una empresa que simplemente decide no registrarse como emisor de facturas cualificadas. La investigación no encontró ningún régimen de multas específico vinculado a la falta de registro en sí.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📉 El coste real es comercial, no punitivo', NULL, NULL, 'Un proveedor no registrado puede seguir comerciando libremente, pero sus clientes empresariales no pueden deducir el crédito fiscal soportado en su totalidad sobre sus facturas -- solo una parte decreciente durante el período transitorio (del 80% al 30% entre 2030 y 2031). Eso convierte a un proveedor no registrado en una contraparte menos atractiva, especialmente para compradores sensibles al IVA. Es un mecanismo de aplicación económico, de mercado, más cercano en espíritu a un incentivo de mercado que a un régimen de cumplimiento basado en multas.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🗓 Una reducción escalonada, no un precipicio', NULL, NULL, 'En lugar de una única fecha de mandato con una multa asociada, la palanca de aplicación de Japón es la reducción gradual del propio alivio transitorio: 80% (2023-2026), 70% (2026-2028), 50% (2028-2030), 30% (2030-2031). La presión para registrarse se acumula a lo largo de casi una década, no de la noche a la mañana.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📋 El riesgo fiscal ordinario sigue aplicándose', NULL, NULL, 'Aunque no existe una sanción específica de la factura, las normas generales del impuesto al consumo de Japón -- sanciones por declaraciones inexactas, requisitos de conservación de registros -- siguen aplicándose con normalidad. Consignar incorrectamente el contenido de una factura cualificada, o no conservar los registros durante los 7 años exigidos, puede seguir generando exposición fiscal indirecta, aunque el Sistema de Facturas Cualificadas en sí no tenga un régimen de multas propio.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme su estado de registro ante la NTA', 'Si sus clientes empresariales dependen de sus facturas para el crédito fiscal soportado, confirme que está registrado como emisor de facturas cualificadas y tenga listo su número T de 14 dígitos para mostrarlo.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Compruebe la compatibilidad de su software de facturación con el campo del número T', 'Asegúrese de que su plantilla o software de facturación puede mostrar su número T junto con los otros cinco elementos obligatorios de la factura cualificada -- nombre del emisor, fecha de emisión, descripción detallada, importes diferenciados por tipo impositivo y el total del impuesto al consumo.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Decida si la adopción de JP PINT/Peppol tiene sentido para usted', 'Dado que la emisión electrónica es totalmente opcional, valore si adoptar JP PINT merece la pena según los planes y sistemas de sus socios comerciales concretos -- no hay ningún requisito de cumplimiento que le empuje hacia ello.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Siga la reducción escalonada del alivio transitorio si compra a proveedores no registrados', 'Presupueste la disminución de la parte deducible en las compras a proveedores no registrados -- 70% desde octubre de 2026, 50% desde octubre de 2028, 30% desde octubre de 2030.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Esté atento a futuras actualizaciones de la especificación JP PINT', 'JP PINT alcanzó la versión 1.1.3 a 8 de junio de 2026 -- consulte periódicamente la propia página de JP PINT de la Agencia Digital si ha adoptado, o está considerando adoptar, el estándar.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Agencia Digital — JP PINT (especificación de facturación electrónica Peppol de Japón)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Japan' AND pt.sort_order = 0;
