INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Freiwillige E-Rechnung (JP PINT / Peppol), aufgesetzt auf ein seit 2023 verpflichtendes Papier-oder-elektronisch-Qualified-Invoice-System -- keine E-Rechnungspflicht', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der Digital Agency und der Nationalen Steuerbehörde sowie Brancheninformationen mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie den aktuellen Stand direkt bei der NTA, der Digital Agency oder einem japanischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Japans Digital Agency wurde im September 2021 gegründet und wurde die Peppol-Autorität des Landes; einen Monat später begann die Registrierung für das Qualified Invoice System, das am 1. Oktober 2023 in Kraft trat. JP PINT, ein freiwilliger Peppol-E-Rechnungsstandard, hat sich parallel dazu entwickelt, während die Übergangsregelung zum Vorsteuerabzug für nicht registrierte Lieferanten bis 2031 schrittweise sinkt.', 'Es gibt kein vorgeschriebenes Rechnungsdateiformat in Japan -- qualifizierte Rechnungen können auf Papier, als PDF oder in jedem anderen Format vorliegen, solange sie den erforderlichen Inhalt enthalten. Unternehmen, die sich für die elektronische Rechnungsstellung entscheiden, können JP PINT nutzen, Japans freiwillige, Peppol-PINT-BIS-Billing-konforme Spezifikation, die von der Digital Agency gepflegt wird.', 'In Japan gilt keine B2B- oder B2G-E-Rechnungspflicht -- jedes Unternehmen kann weiterhin Papier-, PDF- oder elektronische Rechnungen versenden. Das Qualified Invoice System regelt stattdessen den INHALT der Rechnung und die Registrierung des Lieferanten für Zwecke des Vorsteuerabzugs bei der Umsatzsteuer und gilt überall dort, wo ein Geschäftskunde diesen Abzug geltend machen möchte, unabhängig vom Format oder der Art der Übermittlung der Rechnung.', 'Da sich Japan auf keine Ausstellungspflicht vorbereiten muss, besteht die praktische Arbeit hier größtenteils aus den Registrierungs- und Inhaltsanforderungen des Qualified Invoice System -- sowie der rein freiwilligen Entscheidung, ob sich die Einführung von JP PINT/Peppol für Ihre Handelsbeziehungen lohnt.', 'Japans Qualified Invoice System sieht keine direkte finanzielle Sanktion für ein Unternehmen vor, das sich nicht registriert -- der Durchsetzungsmechanismus ist wirtschaftlicher, nicht strafender Natur: Die Rechnungen eines nicht registrierten Lieferanten ermöglichen seinen Geschäftskunden keinen vollen Vorsteuerabzug, ein Marktnachteil statt einer Geldstrafe.', 'Japan hat keine E-Rechnungspflicht -- Papier- und PDF-Rechnungen bleiben vollständig gültig. Verpflichtend ist seit dem 1. Oktober 2023 das Qualified Invoice System: Um den Vorsteuerabzug geltend zu machen, benötigt ein Geschäftskunde in der Regel eine Rechnung eines bei der NTA registrierten Lieferanten mit bestimmtem Inhalt, einschließlich einer 14-stelligen T-Nummer -- ein Registrierungs- und Dokumentationssystem, keine Vorschrift zum Übermittlungsformat. Daneben fördert die Digital Agency seit 2021 JP PINT, einen freiwilligen, Peppol-basierten E-Rechnungsstandard. Die Übergangsregelung für den Vorsteuerabzug bei Einkäufen von nicht registrierten Lieferanten sinkt bereits schrittweise bis 2031.', '🇯🇵' FROM countries WHERE name_en = 'Japan';

