INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '7 Jahre', 'Aufbewahrungspflicht für Rechnungen' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Japan' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Pflichtinhalt der qualifizierten Rechnung', '[["Ausstellerangaben", "Name des Ausstellers und 14-stellige T-Nummer (Registrierungsnummer)"], ["Ausstellungsdatum", "Datum der Rechnungsausstellung"], ["Detaillierte Beschreibung", "Beschreibung der gelieferten Waren/Dienstleistungen"], ["Nach Steuersatz getrennte Beträge", "Nach geltendem Umsatzsteuersatz (Standard/ermäßigt) aufgeschlüsselte Beträge"], ["Gesamtbetrag der Umsatzsteuer", "Gesamtbetrag der Umsatzsteuer für die Rechnung"]]', 'Nichts davon verlangt, dass die Rechnung elektronisch ausgestellt wird -- eine Papier- oder PDF-Rechnung mit diesem Inhalt ist eine vollständig gültige qualifizierte Rechnung.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'JP PINT / Peppol-Spezifikation (freiwillig)', '[["Standard", "JP PINT -- Japans Peppol-PINT-BIS-Billing-konforme E-Rechnungsspezifikation"], ["Governance", "Entwickelt von der Digital Agency gemeinsam mit EIPA, einem japanischen Branchenverband"], ["Aktuelle Version", "v1.1.3 (Stand 8. Juni 2026), umfasst die Standard Invoice JP PINT, die JP BIS Self-Billing Invoice und die JP BIS Invoice for Non-tax-Registered Businesses"], ["Rechtlicher Status", "Vollständig freiwillig -- kein Gesetz verlangt die Einführung"]]', 'JP PINT ist eine echte, aktiv gepflegte Spezifikation -- sie ist lediglich für kein Unternehmen verpflichtend.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Registrierung & Aufbewahrung', '[["Registrierungsbehörde", "Nationale Steuerbehörde (NTA)"], ["Registrierungszeitraum", "Ab dem 1. Oktober 2021 geöffnet, im Vorgriff auf das Inkrafttreten am 1. Oktober 2023"], ["Format der T-Nummer", "Eine 14-stellige Registrierungsnummer, die jedem registrierten qualifizierten Rechnungsaussteller zugewiesen wird"], ["Aufbewahrungsfrist", "Mindestens 7 Jahre für qualifizierte Rechnungen und zugehörige Aufzeichnungen"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der freiwillige JP-PINT-/Peppol-Ablauf', 'Für die Minderheit der Unternehmen, die sich für die elektronische Rechnungsstellung über JP PINT entscheiden, durchläuft eine Rechnung diese Abfolge -- bei jedem Schritt vollständig freiwillig:', 'Nichts an diesem Ablauf ist verpflichtend. Die meisten japanischen Unternehmen tauschen weiterhin Papier- oder PDF-Rechnungen aus und bleiben vollständig konform mit dem Qualified Invoice System, solange der Rechnungsinhalt korrekt ist.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Das System des Lieferanten erstellt eine E-Rechnung im JP-PINT-Format' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Versand über den Peppol Access Point des Lieferanten' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Übermittlung über das Peppol-Vier-Ecken-Netzwerk' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Zustellung an den Access Point des Käufers' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Direkter Empfang im System des Käufers als strukturierte Daten' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was heute tatsächlich verpflichtend gegenüber freiwillig ist, nach Ebenen', '[["Rechnungsformat/-ausstellung", "Nicht vorgeschrieben -- Papier, PDF oder elektronisch, alle gültig"], ["Inhalt und Registrierung der qualifizierten Rechnung", "Verpflichtend seit 1. Okt. 2023, für Zwecke des Vorsteuerabzugs"], ["Einführung von JP PINT / Peppol", "Vollständig freiwillig, staatlich unterstützter Standard"], ["Allgemeine B2B-E-Rechnungspflicht", "Existiert nicht -- kein Vorschlag mit festem Zeitplan gefunden"]]', 'Es ist leicht, Japans echte Steuerpflicht von 2023 mit einer E-Rechnungspflicht zu verwechseln -- das ist nicht dasselbe. Nur Ersteres ist gesetzlich vorgeschrieben.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Die stufenweise Reduzierung der Übergangsregelung', '[["1. Okt. 2023 - 30. Sept. 2026", "80 % der Steuer auf Einkäufe von nicht registrierten Lieferanten abzugsfähig"], ["1. Okt. 2026 - 30. Sept. 2028", "70 % abzugsfähig"], ["1. Okt. 2028 - 30. Sept. 2030", "50 % abzugsfähig"], ["1. Okt. 2030 - 30. Sept. 2031", "30 % abzugsfähig"]]', 'Die geprüfte NTA-Quelle bestätigte den Endzustand nach September 2031 nicht ausdrücklich -- betrachten Sie die vollständige Abschaffung nach diesem Datum als erwartet, hier jedoch nicht offiziell bestätigt.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💰 Keine direkte Geldstrafe für unterlassene Registrierung', NULL, NULL, 'Anders als in vielen in diesem Tracker erfassten Rechtsordnungen sieht Japans Qualified Invoice System keine direkte finanzielle Sanktion für ein Unternehmen vor, das sich einfach nicht als qualifizierter Rechnungsaussteller registriert. Die Recherche ergab kein eigenes Bußgeldschema, das an die Nichtregistrierung selbst geknüpft ist.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📉 Die eigentlichen Kosten sind wirtschaftlicher, nicht strafender Natur', NULL, NULL, 'Ein nicht registrierter Lieferant kann weiterhin frei Handel treiben, doch seine Geschäftskunden können keinen vollen Vorsteuerabzug auf seine Rechnungen geltend machen -- nur einen während der Übergangsperiode schrumpfenden Anteil (von 80 % auf 30 % bis 2030-2031 sinkend). Das macht einen nicht registrierten Lieferanten zu einem weniger attraktiven Geschäftspartner, insbesondere für umsatzsteuersensible Käufer. Es handelt sich um einen wirtschaftlichen, marktbasierten Durchsetzungsmechanismus, der eher einem Marktanreiz ähnelt als einem bußgeldbasierten Compliance-Regime.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🗓 Eine schrittweise Reduzierung, kein abrupter Einschnitt', NULL, NULL, 'Statt eines einzigen Pflichtdatums mit angehängter Geldstrafe ist Japans Durchsetzungshebel die schrittweise Reduzierung der Übergangsregelung selbst: 80 % (2023-2026), 70 % (2026-2028), 50 % (2028-2030), 30 % (2030-2031). Der Registrierungsdruck baut sich über fast ein Jahrzehnt auf, nicht über Nacht.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📋 Gewöhnliches Steuer-Compliance-Risiko besteht weiterhin', NULL, NULL, 'Auch wenn es keine rechnungsspezifische Sanktion gibt, gelten Japans allgemeine Umsatzsteuerregeln -- Sanktionen für unrichtige Erklärungen, Aufbewahrungspflichten -- weiterhin uneingeschränkt. Ein fehlerhafter Inhalt einer qualifizierten Rechnung oder die Nichteinhaltung der vorgeschriebenen 7-jährigen Aufbewahrungsfrist kann weiterhin zu nachgelagerten steuerlichen Risiken führen, auch wenn das Qualified Invoice System selbst über kein eigenes Bußgeldschema verfügt.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie Ihren Registrierungsstatus bei der NTA', 'Wenn sich Ihre Geschäftskunden für den Vorsteuerabzug auf Ihre Rechnungen verlassen, stellen Sie sicher, dass Sie als qualifizierter Rechnungsaussteller registriert sind und Ihre 14-stellige T-Nummer bereithalten.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie die Unterstützung des T-Nummer-Felds in Ihrer Rechnungssoftware', 'Stellen Sie sicher, dass Ihre Rechnungsvorlage oder -software Ihre T-Nummer zusammen mit den übrigen fünf Pflichtangaben der qualifizierten Rechnung anzeigen kann -- Ausstellername, Ausstellungsdatum, detaillierte Beschreibung, nach Steuersatz getrennte Beträge und den Gesamtbetrag der Umsatzsteuer.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Entscheiden Sie, ob die Einführung von JP PINT/Peppol für Sie sinnvoll ist', 'Da die elektronische Ausstellung vollständig freiwillig ist, wägen Sie ab, ob sich die Einführung von JP PINT angesichts der Pläne und Systeme Ihrer konkreten Handelspartner lohnt -- es gibt keine Compliance-Anforderung, die Sie dazu drängt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Verfolgen Sie die stufenweise Reduzierung der Übergangsregelung, wenn Sie von nicht registrierten Lieferanten einkaufen', 'Kalkulieren Sie den sinkenden abzugsfähigen Anteil bei Einkäufen von nicht registrierten Lieferanten ein -- 70 % ab Oktober 2026, 50 % ab Oktober 2028, 30 % ab Oktober 2030.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Achten Sie auf künftige Aktualisierungen der JP-PINT-Spezifikation', 'JP PINT erreichte zum 8. Juni 2026 Version 1.1.3 -- prüfen Sie regelmäßig die eigene JP-PINT-Seite der Digital Agency, wenn Sie den Standard eingeführt haben oder dessen Einführung erwägen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 4;

