-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Facturation électronique volontaire (JP PINT / Peppol) superposée à un régime des factures qualifiées obligatoire, papier ou électronique, depuis 2023 -- aucune obligation de facturation électronique', 'Cette page d''analyse reflète les indications publiques de l''Agence numérique et de l''administration fiscale nationale, ainsi que les informations sectorielles disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez le statut actuel directement auprès de la NTA, de l''Agence numérique ou d''un conseiller fiscal japonais avant de fonder vos décisions de conformité sur cette page.', 'L''Agence numérique du Japon a été créée en septembre 2021 et est devenue l''Autorité Peppol du pays ; un mois plus tard, les inscriptions au régime des factures qualifiées se sont ouvertes, celui-ci entrant en vigueur le 1er octobre 2023. JP PINT, une norme Peppol volontaire de facturation électronique, s''est développée en parallèle, tandis que l''allègement transitoire du crédit de taxe en amont pour les fournisseurs non enregistrés diminue progressivement jusqu''en 2031.', 'Il n''existe aucun format de fichier de facture imposé au Japon -- les factures qualifiées peuvent être au format papier, PDF ou tout autre format, tant qu''elles contiennent le contenu requis. Les entreprises qui choisissent de facturer électroniquement peuvent utiliser JP PINT, la spécification volontaire du Japon conforme à Peppol PINT BIS Billing, maintenue par l''Agence numérique.', 'Aucune obligation de facturation électronique B2B ou B2G ne s''applique au Japon -- toute entreprise reste libre d''envoyer des factures papier, PDF ou électroniques. Le régime des factures qualifiées régit à la place le CONTENU de la facture et l''enregistrement du fournisseur à des fins de crédit de taxe à la consommation en amont, et s''applique dès qu''un client professionnel souhaite demander ce crédit, quel que soit le format ou le mode de transmission de la facture.', 'Le Japon n''ayant aucune obligation d''émission à laquelle se préparer, l''essentiel du travail pratique ici concerne les exigences d''enregistrement et de contenu du régime des factures qualifiées -- ainsi que la décision, entièrement facultative, de savoir si l''adoption de JP PINT/Peppol vaut la peine pour vos relations commerciales.', 'Le régime des factures qualifiées du Japon ne prévoit aucune sanction financière directe pour une entreprise qui ne s''enregistre pas -- le mécanisme d''application est économique, non punitif : les factures d''un fournisseur non enregistré ne permettent pas à ses clients professionnels de déduire intégralement le crédit de taxe en amont, un désavantage commercial plutôt qu''une amende.', 'Le Japon n''a aucune obligation de facturation électronique -- les factures papier et PDF restent pleinement valables. Ce qui est obligatoire, depuis le 1er octobre 2023, c''est le régime des factures qualifiées : pour demander le crédit de taxe en amont, un client professionnel a généralement besoin d''une facture émise par un fournisseur enregistré auprès de la NTA et comportant un contenu précis, y compris un numéro T à 14 chiffres -- un régime d''enregistrement et de documentation, non une règle de format de transmission. Par ailleurs, l''Agence numérique promeut JP PINT, une norme volontaire de facturation électronique fondée sur Peppol, depuis 2021. L''allègement transitoire du crédit pour les achats auprès de fournisseurs non enregistrés diminue déjà progressivement jusqu''en 2031.', '🇯🇵' FROM countries WHERE name_en = 'Japan';

