INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Contenu obligatoire de la facture qualifiée', '[["Informations sur l''émetteur", "Nom de l''émetteur et numéro T à 14 chiffres (numéro d''enregistrement)"], ["Date d''émission", "Date à laquelle la facture a été émise"], ["Description détaillée", "Description des biens/services fournis"], ["Montants différenciés par taux de taxe", "Montants ventilés selon le taux de taxe à la consommation applicable (normal/réduit)"], ["Total de la taxe à la consommation", "Montant total de la taxe à la consommation de la facture"]]', 'Rien de tout cela n''exige que la facture soit émise électroniquement -- une facture papier ou PDF contenant ce contenu est une facture qualifiée pleinement valable.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Spécification JP PINT / Peppol (volontaire)', '[["Norme", "JP PINT -- la spécification de facturation électronique du Japon conforme à Peppol PINT BIS Billing"], ["Gouvernance", "Développée par l''Agence numérique avec EIPA, un organisme sectoriel japonais"], ["Version actuelle", "v1.1.3 (au 8 juin 2026), couvrant la Standard Invoice JP PINT, la JP BIS Self-Billing Invoice et la JP BIS Invoice for Non-tax-Registered Businesses"], ["Statut juridique", "Entièrement volontaire -- aucune loi n''impose son adoption"]]', 'JP PINT est une spécification réelle et activement maintenue -- elle n''est simplement obligatoire pour aucune entreprise.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Enregistrement et conservation', '[["Autorité d''enregistrement", "Administration fiscale nationale (NTA)"], ["Fenêtre d''enregistrement", "Ouverte depuis le 1er octobre 2021, en amont de l''entrée en vigueur le 1er octobre 2023"], ["Format du numéro T", "Un numéro d''enregistrement à 14 chiffres attribué à chaque émetteur de factures qualifiées enregistré"], ["Durée de conservation", "Minimum 7 ans pour les factures qualifiées et les documents associés"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux volontaire JP PINT/Peppol', 'Pour la minorité d''entreprises qui choisissent de facturer électroniquement via JP PINT, une facture suit cette séquence -- entièrement facultative à chaque étape :', 'Rien dans ce flux n''est obligatoire. La plupart des entreprises japonaises continuent d''échanger des factures papier ou PDF et restent pleinement conformes au régime des factures qualifiées tant que le contenu de la facture est correct.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le système du fournisseur génère une facture électronique au format JP PINT' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Envoi via le point d''accès Peppol du fournisseur' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Transmission sur le réseau Peppol à quatre coins' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Livraison au point d''accès de l''acheteur' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Réception directe dans le système de l''acheteur sous forme de données structurées' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Japan' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce qui est réellement obligatoire ou volontaire, par niveau', '[["Format/émission de la facture", "Non imposé -- papier, PDF ou électronique, tous valables"], ["Contenu et enregistrement de la facture qualifiée", "Obligatoire depuis le 1er oct. 2023, à des fins de crédit de taxe en amont"], ["Adoption de JP PINT / Peppol", "Entièrement volontaire, norme soutenue par le gouvernement"], ["Obligation générale de facturation électronique B2B", "N''existe pas -- aucune proposition avec un calendrier fixé n''a été trouvée"]]', 'Il est facile de confondre la véritable obligation fiscale de 2023 du Japon avec une obligation de facturation électronique -- ce n''est pas la même chose. Seule la première est légalement requise.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'La réduction progressive de l''allègement transitoire', '[["1er oct. 2023 - 30 sept. 2026", "80 % de la taxe sur les achats auprès de fournisseurs non enregistrés déductible"], ["1er oct. 2026 - 30 sept. 2028", "70 % déductible"], ["1er oct. 2028 - 30 sept. 2030", "50 % déductible"], ["1er oct. 2030 - 30 sept. 2031", "30 % déductible"]]', 'La source de la NTA consultée n''a pas explicitement confirmé l''issue après septembre 2031 -- considérez la suppression totale après cette date comme attendue, mais non officiellement confirmée ici.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💰 Aucune amende directe pour absence d''enregistrement', NULL, NULL, 'Contrairement à de nombreuses juridictions couvertes par ce suivi, le régime des factures qualifiées du Japon ne prévoit aucune sanction financière directe pour une entreprise qui choisit simplement de ne pas s''enregistrer en tant qu''émetteur de factures qualifiées. Les recherches n''ont révélé aucun barème d''amendes propre au défaut d''enregistrement lui-même.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📉 Le coût réel est commercial, pas punitif', NULL, NULL, 'Un fournisseur non enregistré peut continuer à commercer librement, mais ses clients professionnels ne peuvent pas déduire intégralement le crédit de taxe en amont sur ses factures -- seulement une part décroissante pendant la période transitoire (de 80 % à 30 % d''ici 2030-2031). Cela rend un fournisseur non enregistré moins attractif comme partenaire commercial, en particulier pour les acheteurs sensibles à la TVA. Il s''agit d''un mécanisme d''application économique, fondé sur le marché, plus proche dans son esprit d''une incitation de marché que d''un régime de conformité fondé sur des amendes.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🗓 Une réduction progressive, pas un effet de seuil', NULL, NULL, 'Plutôt qu''une seule date d''obligation assortie d''une amende, le levier d''application du Japon est la réduction progressive de l''allègement transitoire lui-même : 80 % (2023-2026), 70 % (2026-2028), 50 % (2028-2030), 30 % (2030-2031). La pression à s''enregistrer s''accumule sur près d''une décennie, pas du jour au lendemain.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📋 Le risque fiscal ordinaire continue de s''appliquer', NULL, NULL, 'Bien qu''il n''existe pas de sanction propre à la facture, les règles générales de la taxe à la consommation au Japon -- sanctions pour déclarations inexactes, obligations de conservation des documents -- continuent de s''appliquer normalement. Un contenu de facture qualifiée erroné, ou le non-respect de la durée de conservation obligatoire de 7 ans, peut toujours entraîner une exposition fiscale indirecte, même si le régime des factures qualifiées lui-même ne comporte pas de barème d''amendes propre.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Japan' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez votre statut d''enregistrement auprès de la NTA', 'Si vos clients professionnels s''appuient sur vos factures pour le crédit de taxe en amont, vérifiez que vous êtes enregistré en tant qu''émetteur de factures qualifiées et tenez votre numéro T à 14 chiffres prêt à être affiché.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez la prise en charge du champ numéro T par votre logiciel de facturation', 'Assurez-vous que votre modèle ou logiciel de facturation peut afficher votre numéro T ainsi que les cinq autres éléments obligatoires de la facture qualifiée -- nom de l''émetteur, date d''émission, description détaillée, montants différenciés par taux de taxe et total de la taxe à la consommation.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Décidez si l''adoption de JP PINT/Peppol est pertinente pour vous', 'L''émission électronique étant entièrement facultative, évaluez si l''adoption de JP PINT vaut la peine compte tenu des plans et systèmes de vos partenaires commerciaux spécifiques -- aucune exigence de conformité ne vous y pousse.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Suivez la réduction progressive de l''allègement transitoire si vous achetez auprès de fournisseurs non enregistrés', 'Prévoyez la baisse de la part déductible sur les achats auprès de fournisseurs non enregistrés -- 70 % à partir d''octobre 2026, 50 % à partir d''octobre 2028, 30 % à partir d''octobre 2030.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Surveillez les futures mises à jour de la spécification JP PINT', 'JP PINT a atteint la version 1.1.3 au 8 juin 2026 -- consultez régulièrement la page JP PINT de l''Agence numérique si vous avez adopté la norme, ou envisagez de le faire.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Japan' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Agence numérique — JP PINT (spécification de facturation électronique Peppol du Japon)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Japan' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Administration fiscale nationale (NTA) — régime des factures qualifiées' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Japan' AND pt.sort_order = 1;
